<?php
require_once __DIR__ . '/includes/visitor_portal.php';
$pdo=db();$visitor=current_visitor($pdo);$error='';$success='';$bookBarcode=trim($_POST['book_barcode']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$photo=save_captured_photo(trim($_POST['return_photo']??''),'guest-return-'.$visitor['id']);if($bookBarcode==='')$error='Scan or enter the book barcode.';elseif(!$photo)$error='Capture a live photo while holding the returned book.';else{$s=$pdo->prepare('SELECT vb.*,b.title FROM visitor_borrowing vb JOIN books b ON b.id=vb.book_id WHERE vb.visitor_id=? AND b.barcode=? AND vb.request_status="Released" AND vb.return_date IS NULL LIMIT 1');$s->execute([$visitor['id'],$bookBarcode]);$loan=$s->fetch();if(!$loan)$error='No active guest loan was found for that barcode.';else{$pdo->prepare('UPDATE visitor_borrowing SET request_status="Return Verification Pending",return_verification_photo=?,return_requested_at=NOW() WHERE id=?')->execute([$photo,$loan['id']]);visitor_log($pdo,$visitor['id'],'return_verification','Return evidence captured for '.$loan['title']);$success='Return verification submitted. Please hand the book to the librarian for completion.';}}}
visitor_portal_header('Return a Book',$visitor);
?><h2>Return a Book</h2><p class="text-muted">Scan the book, then take a clear photo while holding the returned book.</p><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><div class="card"><div class="card-body"><form method="post"><?=csrf_field()?><input class="form-control mb-3" name="book_barcode" autofocus placeholder="Scan or enter book barcode" value="<?=e($bookBarcode)?>"><input type="hidden" id="return_photo" name="return_photo"><div class="position-relative text-center"><video id="cam" autoplay playsinline muted style="width:420px;max-width:100%;background:#111;border-radius:10px"></video><div class="position-absolute top-50 start-50 translate-middle border border-3 border-warning rounded" style="width:55%;height:34%;pointer-events:none;animation:pulse 1.5s infinite"></div><p class="small">Hold the returned book below your chest. Keep your face and the book cover visible.</p><canvas id="snap" class="d-none"></canvas><img id="preview" class="d-none img-fluid rounded" style="max-width:420px" alt="Return verification preview"></div><button type="button" id="start" class="btn btn-outline-primary">Start Camera</button><button type="button" id="capture" class="btn btn-success d-none">Capture</button><button type="button" id="retake" class="btn btn-outline-secondary d-none">Retake</button><button class="btn btn-success float-end">Submit Return</button></form></div></div><style>@keyframes pulse{50%{opacity:.35}}</style><script>(()=>{let st;start.onclick=()=>navigator.mediaDevices.getUserMedia({video:true}).then(s=>{st=s;cam.srcObject=s;start.classList.add('d-none');capture.classList.remove('d-none')});capture.onclick=()=>{snap.width=cam.videoWidth;snap.height=cam.videoHeight;snap.getContext('2d').drawImage(cam,0,0,snap.width,snap.height);return_photo.value=snap.toDataURL('image/jpeg',.85);preview.src=return_photo.value;preview.classList.remove('d-none');cam.classList.add('d-none');st.getTracks().forEach(t=>t.stop());capture.classList.add('d-none');retake.classList.remove('d-none')};retake.onclick=()=>location.reload()})()</script><?php visitor_portal_footer(); ?>
